CREATE TABLE `xt_chungchi` (
  `id_cc` int NOT NULL AUTO_INCREMENT,
  `cccd` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Mã CCCD của thí sinh',
  `loai_chung_chi` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'VD: Tiếng Anh - IELTS',
  `diem_chung_chi` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'VD: 7.5, 8.0, 8/C1',
  `diem_quydoi` double NOT NULL DEFAULT '0' COMMENT 'Điểm quy đổi đắp vào môn Tiếng Anh',
  `diem_cong` double NOT NULL DEFAULT '0' COMMENT 'Điểm cộng thêm vào tổng điểm',
  PRIMARY KEY (`id_cc`)
) ENGINE=InnoDB AUTO_INCREMENT=4400 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
