  `hsmon2` int DEFAULT NULL,
  `th_mon3` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `hsmon3` int DEFAULT NULL,
  `tb_keys` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'manganh_matohop',
  `N1` int DEFAULT NULL,
  `TO` int DEFAULT NULL,
  `LI` int DEFAULT NULL,
  `HO` int DEFAULT NULL,
  `SI` int DEFAULT NULL,
  `VA` int DEFAULT NULL,
  `SU` int DEFAULT NULL,
  `DI` int DEFAULT NULL,
  `TI` int DEFAULT NULL,
  `KHAC` int DEFAULT NULL,
  `KTPL` int DEFAULT NULL,
  `dolech` double DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `key_UNIQUE` (`tb_keys`)
) ENGINE=InnoDB AUTO_INCREMENT=1466 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
